const body = $input.first().json.body || $input.first().json;

const errors = [];

if (!body.feature_name) errors.push('feature_name required');
if (!body.feature_description) errors.push('feature_description required');

if (errors.length > 0) {
  return [{
    json: {
      success: false,
      errors: errors
    }
  }];
}

return [{
  json: {
    feature_name: body.feature_name,
    feature_description: body.feature_description,
    video_duration: body.video_duration || 60,
    avatar_id: body.avatar_id || 'josh_lite3_20230714',
    voice_id: body.voice_id || 'en-US-Neural2-A',
    style: body.style || 'professional',
    include_motion_graphics: body.include_motion_graphics !== false
  }
}];

