const response = $input.first().json;
const content = response.content[0].text;

// Extract JSON from response
const jsonMatch = content.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('No valid JSON found in Claude response');
}

const script = JSON.parse(jsonMatch[0]);

console.log('Generated script:', script.full_script);
console.log('Scenes with motion graphics:', script.scenes.length);

return [{
  json: {
    ...($('Input Validation').first().json),
    script: script
  }
}];

const data = $input.first().json;
const script = data.script;

// Generate Remotion composition code
const remotionComposition = `
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from 'remotion';
import React from 'react';

export const ScreeningPilotVideo = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  ${script.scenes.map((scene, idx) => {
    const startFrame = script.scenes.slice(0, idx).reduce((sum, s) => sum + (s.duration * fps), 0);
    const endFrame = startFrame + (scene.duration * fps);

    return `
    // ${scene.name.toUpperCase()} SCENE (${scene.duration}s)
    {frame >= ${startFrame} && frame < ${endFrame} && (
      <Scene${idx} frame={frame - ${startFrame}} fps={fps} data={${JSON.stringify(scene.motion_graphics)}} />
    )}
    `;
  }).join('\n')}

  return (
    <AbsoluteFill style={{ backgroundColor: '${script.brand_colors.background}' }}>
      {/* Scenes render here */}
    </AbsoluteFill>
  );
};

${script.scenes.map((scene, idx) => `
const Scene${idx} = ({ frame, fps, data }) => {
  return (
    <AbsoluteFill>
      {/* Background */}
      ${scene.motion_graphics.background.type === 'gradient' ? `
      <div style={{
        position: 'absolute',
        width: '100%',
        height: '100%',
        background: 'linear-gradient(135deg, ${scene.motion_graphics.background.colors.join(', ')})'
      }} />
      ` : `
      <div style={{
        position: 'absolute',
        width: '100%',
        height: '100%',
        backgroundColor: '${scene.motion_graphics.background.value}'
      }} />
      `}

      {/* Elements */}
      ${scene.motion_graphics.elements.map((el, elIdx) => {
        if (el.type === 'text') {
          return `
          {frame >= ${el.timing.start * fps} && frame < ${(el.timing.start + el.timing.duration) * fps} && (
            <AnimatedText
              text="${el.content}"
              fontSize={${el.fontSize}}
              color="${el.color}"
              position={{ x: "${el.position.x}", y: ${el.position.y} }}
              frame={frame - ${el.timing.start * fps}}
              animation="${el.animation}"
            />
          )}
          `;
        }

        if (el.type === 'counter') {
          return `
          {frame >= ${el.timing.start * fps} && frame < ${(el.timing.start + el.timing.duration) * fps} && (
            <AnimatedCounter
              from={${el.from}}
              to={${el.to}}
              fontSize={${el.fontSize}}
              color="${el.color}"
              position={{ x: "${el.position.x}", y: ${el.position.y} }}
              frame={frame - ${el.timing.start * fps}}
              duration={${el.duration * fps}}
            />
          )}
          `;
        }

        if (el.type === 'progress-bar') {
          return `
          {frame >= ${el.timing.start * fps} && frame < ${(el.timing.start + el.timing.duration) * fps} && (
            <ProgressBar
              width={${el.width}}
              height={${el.height}}
              color="${el.color}"
              progress={${el.progress}}
              position={{ x: "${el.position.x}", y: ${el.position.y} }}
              frame={frame - ${el.timing.start * fps}}
              duration={${el.duration * fps}}
            />
          )}
          `;
        }

        if (el.type === 'icon') {
          return `
          {frame >= ${el.timing.start * fps} && frame < ${(el.timing.start + el.timing.duration) * fps} && (
            <AnimatedIcon
              name="${el.name}"
              size={${el.size}}
              color="${el.color}"
              position={{ x: "${el.position.x}", y: ${el.position.y} }}
              frame={frame - ${el.timing.start * fps}}
              animation="${el.animation}"
            />
          )}
          `;
        }
      }).join('\n')}
    </AbsoluteFill>
  );
};
`).join('\n')}

// Helper Components
const AnimatedText = ({ text, fontSize, color, position, frame, animation }) => {
  const opacity = animation === 'fadeIn' 
    ? interpolate(frame, [0, 30], [0, 1], { extrapolateRight: 'clamp' })
    : 1;

  const scale = animation === 'zoomIn'
    ? spring({ frame, fps: 30, from: 0.5, to: 1 })
    : 1;

  return (
    <div style={{
      position: 'absolute',
      fontSize: fontSize,
      color: color,
      fontWeight: 700,
      opacity: opacity,
      transform: \`translate(-50%, -50%) scale(\${scale})\`,
      left: position.x === 'center' ? '50%' : position.x,
      top: position.y
    }}>
      {text}
    </div>
  );
};

const AnimatedCounter = ({ from, to, fontSize, color, position, frame, duration }) => {
  const value = Math.round(interpolate(frame, [0, duration], [from, to], { extrapolateRight: 'clamp' }));

  return (
    <div style={{
      position: 'absolute',
      fontSize: fontSize,
      color: color,
      fontWeight: 700,
      transform: 'translate(-50%, -50%)',
      left: position.x === 'center' ? '50%' : position.x,
      top: position.y
    }}>
      {value.toLocaleString()}
    </div>
  );
};

const ProgressBar = ({ width, height, color, progress, position, frame, duration }) => {
  const currentProgress = interpolate(frame, [0, duration], [0, progress], { extrapolateRight: 'clamp' });

  return (
    <div style={{
      position: 'absolute',
      width: width,
      height: height,
      backgroundColor: 'rgba(255,255,255,0.1)',
      borderRadius: height / 2,
      transform: 'translateX(-50%)',
      left: position.x === 'center' ? '50%' : position.x,
      top: position.y,
      overflow: 'hidden'
    }}>
      <div style={{
        width: \`\${currentProgress}%\`,
        height: '100%',
        backgroundColor: color,
        borderRadius: height / 2,
        transition: 'width 0.3s ease'
      }} />
    </div>
  );
};

const AnimatedIcon = ({ name, size, color, position, frame, animation }) => {
  const scale = animation === 'bounce'
    ? spring({ frame, fps: 30, from: 0, to: 1, config: { damping: 8, stiffness: 200 } })
    : 1;

  // Icon SVGs (add more as needed)
  const icons = {
    search: '<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>',
    check: '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>',
    users: '<svg viewBox="0 0 24 24"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>'
  };

  return (
    <div style={{
      position: 'absolute',
      width: size,
      height: size,
      color: color,
      transform: \`translate(-50%, -50%) scale(\${scale})\`,
      left: position.x === 'center' ? '50%' : position.x,
      top: position.y
    }} dangerouslySetInnerHTML={{ __html: icons[name] || icons.search }} />
  );
};
`;

return [{
  json: {
    feature_name: data.feature_name,
    script: script,
    remotion_composition: remotionComposition,
    video_config: {
      width: 1920,
      height: 1080,
      fps: 30,
      durationInFrames: script.scenes.reduce((sum, s) => sum + s.duration, 0) * 30
    }
  }
}];

const fs = require('fs');
const path = require('path');
const data = $input.first().json;

// Create temporary directory for this video
const videoId = Date.now().toString();
const workDir = `/tmp/remotion-${videoId}`;

if (!fs.existsSync(workDir)) {
  fs.mkdirSync(workDir, { recursive: true });
}

// Write composition file
const compositionPath = path.join(workDir, 'Composition.tsx');
fs.writeFileSync(compositionPath, data.remotion_composition);

// Write remotion config
const configContent = `
import { Config } from '@remotion/cli/config';

Config.setVideoImageFormat('jpeg');
Config.setOverwriteOutput(true);
`;

const configPath = path.join(workDir, 'remotion.config.ts');
fs.writeFileSync(configPath, configContent);

console.log('Remotion files saved to:', workDir);

return [{
  json: {
    ...data,
    work_dir: workDir,
    composition_path: compositionPath
  }
}];

const data = $input.first().json;
const script = data.script;
const backgroundVideoUrl = "https://dummy-url.com/background.mp4"; // In production, replace with actual upload logic

// Combine all narration into single text
const fullNarration = script.scenes
  .map(s => s.narration)
  .join(' ');

// HeyGen API payload with custom background
const heygenInput = {
  video_inputs: [{
    character: {
      type: 'avatar',
      avatar_id: data.avatar_id,
      avatar_style: 'normal'
    },
    voice: {
      type: 'text',
      input_text: fullNarration,
      voice_id: data.voice_id,
      speed: 1.0
    },
    background: {
      type: 'url',
      url: backgroundVideoUrl  // Use Remotion-generated video as background
    }
  }],
  dimension: {
    width: 1920,
    height: 1080
  },
  aspect_ratio: '16:9',
  test: false,
  caption: true
};

return [{
  json: {
    feature_name: data.feature_name,
    script: script,
    background_video_url: backgroundVideoUrl,
    heygen_input: heygenInput
  }
}];

const response = $input.first().json;

if (!response.data || !response.data.video_id) {
  throw new Error('HeyGen video generation failed: ' + JSON.stringify(response));
}

const videoId = response.data.video_id;

console.log('HeyGen video ID:', videoId);

return [{
  json: {
    feature_name: $('Prepare HeyGen Input').first().json.feature_name,
    script: $('Prepare HeyGen Input').first().json.script,
    background_video_url: $('Prepare HeyGen Input').first().json.background_video_url,
    video_id: videoId,
    status: 'pending'
  }
}];

const response = $input.first().json;
const previousData = $('Extract Video ID').first().json;

const status = response.data.status;
const videoUrl = response.data.video_url;
const thumbnailUrl = response.data.thumbnail_url;

console.log('Status:', status);

if (status === 'failed') {
  throw new Error('HeyGen video generation failed');
}

return [{
  json: {
    ...previousData,
    status: status,
    final_video_url: videoUrl || null,
    thumbnail_url: thumbnailUrl || null,
    is_complete: status === 'completed',
    should_retry: status !== 'completed'
  }
}];

const fs = require('fs');
const workDir = $('Save Remotion Composition to File').first().json.work_dir;

// Delete temporary Remotion files
if (fs.existsSync(workDir)) {
  fs.rmSync(workDir, { recursive: true, force: true });
  console.log('Cleaned up:', workDir);
}

return [$input.first()];
